// Sync Worker
async function syncQueue() {
  const queue = await idb.getAll('mutation_queue');
  for (const item of queue) {
    try {
      const res = await api.sync(item);
      await idb.delete('mutation_queue', item.id);
    } catch (err) {
      if (err.status === 409) resolveConflict(item, err.serverData);
      break; // Dừng để bảo toàn thứ tự mutation
    }
  }
}

